# Rebuild concise implementation: candidate 5 uses only fully-inside main-diagonal points for edge case.
program = '''def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 3]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    ir0, ir1, ic0, ic1 = r0 + 1, r1 - 1, c0 + 1, c1 - 1
    h, w = ir1 - ir0 + 1, ic1 - ic0 + 1
    for r in range(ir0, ir1 + 1):
        for c in range(ic0, ic1 + 1):
            out[r][c] = 4
    markers = [(r - ir0, c - ic0) for r in range(ir0, ir1 + 1)
               for c in range(ic0, ic1 + 1) if grid[r][c] == 3]
    if not markers:
        return out
    rr, cc = markers[0]
    center_r, center_c = (h - 1) // 2, (w - 1) // 2
    if rr == center_r and cc == center_c:
        for r in range(h):
            for c in range(w):
                if max(abs(r - rr), abs(c - cc)) == 2:
                    out[ir0 + r][ic0 + c] = 2
    else:
        if cc == 0:
            families = [((1, 1), (-1, -1), True)]
        else:
            toward_r = -1 if rr <= center_r else 1
            toward_c = -1 if cc <= center_c else 1
            families = [((-toward_r, -toward_c), (toward_r, toward_c), False)]
        for (step_r, step_c), (toward_r, toward_c), require_inside in families:
            for k in range(1, max(h, w) + 2):
                pr, pc = rr + 2 * k * step_r, cc + 2 * k * step_c
                if require_inside and not (0 <= pr < h and 0 <= pc < w):
                    continue
                if 0 <= pr < h:
                    c = pc
                    if c < 0 and toward_c > 0: c = 0
                    elif c >= w and toward_c < 0: c = w - 1
                    while 0 <= c < w:
                        out[ir0 + pr][ic0 + c] = 2
                        c += toward_c
                if 0 <= pc < w:
                    r = pr
                    if r < 0 and toward_r > 0: r = 0
                    elif r >= h and toward_r < 0: r = h - 1
                    while 0 <= r < h:
                        out[ir0 + r][ic0 + pc] = 2
                        r += toward_r
    for r, c in [(r + ir0, c + ic0) for r, c in markers]:
        out[r][c] = 3
    return out
'''
